1	import type { ExtensionAPI } from "@earendil-works/pi-coding-agent";
2	import type { RedactorService } from "../services/redactor.js";
3	import { persistConfig } from "../hooks/persist.js";
4	
5	export function registerPiiCommands(pi: ExtensionAPI, redactor: RedactorService): void {
6	  pi.registerCommand("pii", {
7	    description: "Manage PII redaction (status, toggle, rules)",
8	    getArgumentCompletions: (prefix: string) => {
9	      const subcommands = ["status", "toggle", "rules", "enable", "disable"];
10	      return subcommands
11	        .filter((sc) => sc.startsWith(prefix.trim().toLowerCase()))
12	        .map((sc) => ({ value: sc, label: sc }));
13	    },
14	    handler: async (args, ctx) => {
15	      const parts = args.trim().split(/\s+/);
16	      const action = parts[0]?.toLowerCase() || "status";
17	
18	      if (action === "toggle") {
19	        const next = !redactor.isEnabled();
20	        redactor.setEnabled(next);
21	        persistConfig(pi, redactor);
22	        ctx.ui.setStatus("pii-redact", next ? "PII: On" : "PII: Off");
23	        ctx.ui.notify(`PII redaction is now ${next ? "ENABLED" : "DISABLED"}`, "info");
24	        return;
25	      }
26	
27	      if (action === "enable") {
28	        redactor.setEnabled(true);
29	        persistConfig(pi, redactor);
30	        ctx.ui.setStatus("pii-redact", "PII: On");
31	        ctx.ui.notify("PII redaction ENABLED", "info");
32	        return;
33	      }
34	
35	      if (action === "disable") {
36	        redactor.setEnabled(false);
37	        persistConfig(pi, redactor);
38	        ctx.ui.setStatus("pii-redact", "PII: Off");
39	        ctx.ui.notify("PII redaction DISABLED", "info");
40	        return;
41	      }
42	
43	      if (action === "rules") {
44	        const rules = redactor.getRules();
45	        const ruleList = rules
46	          .map((r) => `• ${r.name} (${r.id}): ${r.enabled ? "enabled" : "disabled"}`)
47	          .join("\n");
48	        ctx.ui.notify(`Active Redaction Rules:\n${ruleList}`, "info");
49	        return;
50	      }
51	
52	      // Default: status
53	      const state = redactor.isEnabled() ? "ACTIVE" : "INACTIVE";
54	      const activeRules = redactor.getRules().filter((r) => r.enabled).length;
55	      ctx.ui.notify(
56	        `PII Redactor status: ${state}\nActive rules: ${activeRules}/${redactor.getRules().length}`,
57	        "info"
58	      );
59	    },
60	  });
61	}
