1	import { compact, generateBranchSummary } from "@earendil-works/pi-coding-agent";
2	import type { ExtensionAPI, ExtensionContext, ToolResultEventResult } from "@earendil-works/pi-coding-agent";
3	import type { RedactorService } from "../services/redactor.js";
4	import {
5	  mapContent,
6	  mapMessage,
7	  mapMessages,
8	  mapSessionEntry,
9	  mapStringsDeep,
10	  restoreAssistantMessage,
11	  restoreStringsInPlace,
12	} from "./messages.js";
13	import { loadConfig, loadVault, persistVaultDelta } from "./persist.js";
14	
15	type JsonValue = unknown;
16	
17	export function registerHooks(pi: ExtensionAPI, redactor: RedactorService): void {
18	  const statusText = () => (redactor.isEnabled() ? "PII: On" : "PII: Off");
19	  const restore = (text: string) => redactor.restore(text);
20	  const vaultHasEntries = () => redactor.getVault().size > 0;
21	
22	  /** Redacts one string and counts redactions, for use as a deep-walker callback. */
23	  const counter = () => {
24	    const state = { count: 0 };
25	    const fn = async (text: string): Promise<string> => {
26	      const result = await redactor.redact(text);
27	      state.count += result.count;
28	      return result.text;
29	    };
30	    return { state, fn };
31	  };
32	
33	  const compactionActive = () => redactor.isEnabled() && redactor.getConfig().maskContextMessages;
34	
35	  /** Resolves the model and auth used to summarize, or notifies and returns null. */
36	  const resolveModelAuth = async (ctx: ExtensionContext, what: string) => {
37	    const model = ctx?.model;
38	    if (!model) {
39	      ctx?.ui?.notify?.(`PII redaction: no model available for ${what}; cancelled to avoid leaking plaintext`, "error");
40	      return null;
41	    }
42	    const auth = await ctx.modelRegistry.getApiKeyAndHeaders(model);
43	    if (!auth.ok) {
44	      ctx?.ui?.notify?.(`PII redaction: ${what} auth failed (${auth.error}); cancelled to avoid leaking plaintext`, "error");
45	      return null;
46	    }
47	    // Provider headers may carry null (= "remove header"); the summarizers only accept strings.
48	    const headers: Record<string, string> = {};
49	    for (const [k, v] of Object.entries(auth.headers ?? {})) {
50	      if (typeof v === "string") headers[k] = v;
51	    }
52	    return { model, apiKey: auth.apiKey, headers };
53	  };
54	
55	  // Restore the vault and settings from the session, and update the footer status
56	  pi.on("session_start", async (_event, ctx) => {
57	    const entries = ctx?.sessionManager?.getEntries?.() ?? [];
58	    if (ctx?.sessionManager) {
59	      loadVault(entries, redactor);
60	      loadConfig(entries, redactor);
61	    }
62	    ctx?.ui?.setStatus?.("pii-redact", statusText());
63	  });
64	
65	  // Intercept user prompts before expansion or dispatch
66	  pi.on("input", async (event, ctx) => {
67	    if (!redactor.isEnabled() || !redactor.getConfig().maskUserInputs) {
68	      return undefined;
69	    }
70	
71	    if (!event || typeof event.text !== "string") {
72	      return undefined;
73	    }
74	
75	    const result = await redactor.redact(event.text);
76	    persistVaultDelta(pi, redactor);
77	    if (result.hasRedactions) {
78	      if (redactor.getConfig().notifyOnRedact) {
79	        ctx?.ui?.notify?.(`Redacted ${result.count} sensitive item(s) from input`, "info");
80	      }
81	      return { action: "transform", text: result.text };
82	    }
83	    return undefined;
84	  });
85	
86	  // Restore tokens in tool arguments so tools operate on real values (works even while redaction is off)
87	  pi.on("tool_call", async (event) => {
88	    if (!event?.input || typeof event.input !== "object" || !vaultHasEntries()) {
89	      return undefined;
90	    }
91	    restoreStringsInPlace(event.input, restore);
92	    return undefined;
93	  });
94	
95	  // Restore assistant replies to plaintext at rest (thinking blocks stay byte-identical)
96	  pi.on("message_end", async (event) => {
97	    if (!event?.message || (event.message as any).role !== "assistant" || !vaultHasEntries()) {
98	      return undefined;
99	    }
100	    const restored = await restoreAssistantMessage(event.message, restore);
101	    return restored !== event.message ? { message: restored } : undefined;
102	  });
103	
104	  // Intercept tool results (e.g. read_file, bash output) before storing in session & sending to model
105	  pi.on("tool_result", async (event, ctx) => {
106	    if (!redactor.isEnabled() || !redactor.getConfig().maskToolResults) {
107	      return undefined;
108	    }
109	
110	    if (!event || !Array.isArray(event.content)) {
111	      return undefined;
112	    }
113	
114	    const { state, fn } = counter();
115	    const content = await mapContent(event.content, fn);
116	    const hasStructured = event.structuredContent !== undefined;
117	    const structuredContent = hasStructured ? await mapStringsDeep(event.structuredContent as JsonValue, fn) : undefined;
118	    persistVaultDelta(pi, redactor);
119	
120	    if (content !== event.content || structuredContent !== event.structuredContent) {
121	      if (redactor.getConfig().notifyOnRedact) {
122	        const toolLabel = event?.toolName ? `${event.toolName} output` : "tool output";
123	        ctx?.ui?.notify?.(`Redacted ${state.count} item(s) from ${toolLabel}`, "info");
124	      }
125	      return (hasStructured ? { content, structuredContent } : { content }) as ToolResultEventResult;
126	    }
127	
128	    return undefined;
129	  });
130	
131	  // Intercept messages in context before LLM requests (all roles; inputs are never mutated)
132	  pi.on("context", async (event) => {
133	    if (!redactor.isEnabled() || !redactor.getConfig().maskContextMessages) {
134	      return undefined;
135	    }
136	
137	    if (!event || !Array.isArray(event.messages)) {
138	      return undefined;
139	    }
140	
141	    const { fn } = counter();
142	    const { messages, changed } = await mapMessages(event.messages, fn);
143	    persistVaultDelta(pi, redactor);
144	    return changed ? { messages } : undefined;
145	  });
146	
147	  // Compaction calls the model directly, bypassing `context`: take it over with redacted input
148	  pi.on("session_before_compact", async (event, ctx) => {
149	    if (!compactionActive()) return undefined;
150	
151	    try {
152	      const auth = await resolveModelAuth(ctx, "compaction");
153	      if (!auth) return { cancel: true };
154	
155	      const { fn } = counter();
156	      const prep = event.preparation;
157	      const preparation = {
158	        ...prep,
159	        messagesToSummarize: (await mapMessages(prep.messagesToSummarize ?? [], fn)).messages,
160	        turnPrefixMessages: (await mapMessages(prep.turnPrefixMessages ?? [], fn)).messages,
161	        previousSummary: prep.previousSummary ? await fn(prep.previousSummary) : prep.previousSummary,
162	      };
163	      const instructions = event.customInstructions ? await fn(event.customInstructions) : undefined;
164	
165	      const result = await compact(preparation, auth.model, auth.apiKey, auth.headers, instructions, event.signal);
166	      return { compaction: { ...result, summary: restore(result.summary) } };
167	    } catch (error) {
168	      if (!event.signal?.aborted) {
169	        const message = error instanceof Error ? error.message : String(error);
170	        ctx?.ui?.notify?.(`PII redaction: compaction failed (${message}); cancelled to avoid leaking plaintext`, "error");
171	      }
172	      return { cancel: true };
173	    } finally {
174	      persistVaultDelta(pi, redactor);
175	    }
176	  });
177	
178	  // Branch summaries also call the model directly
179	  pi.on("session_before_tree", async (event, ctx) => {
180	    if (!compactionActive() || !event?.preparation?.userWantsSummary) return undefined;
181	
182	    try {
183	      const auth = await resolveModelAuth(ctx, "branch summary");
184	      if (!auth) return { cancel: true };
185	
186	      const { fn } = counter();
187	      const prep = event.preparation;
188	      const entries: any[] = [];
189	      for (const entry of prep.entriesToSummarize ?? []) {
190	        entries.push(await mapSessionEntry(entry, fn));
191	      }
192	      const instructions = prep.customInstructions ? await fn(prep.customInstructions) : undefined;
193	
194	      const result = await generateBranchSummary(entries, {
195	        model: auth.model,
196	        apiKey: auth.apiKey,
197	        headers: auth.headers,
198	        signal: event.signal,
199	        customInstructions: instructions,
200	        replaceInstructions: prep.replaceInstructions,
201	      });
202	      if (result.aborted) return { cancel: true };
203	      if (result.error || !result.summary) {
204	        throw new Error(result.error ?? "empty summary");
205	      }
206	      return {
207	        summary: {
208	          summary: restore(result.summary),
209	          details: { readFiles: result.readFiles ?? [], modifiedFiles: result.modifiedFiles ?? [] },
210	          usage: result.usage,
211	        },
212	      };
213	    } catch (error) {
214	      if (!event.signal?.aborted) {
215	        const message = error instanceof Error ? error.message : String(error);
216	        ctx?.ui?.notify?.(`PII redaction: branch summary failed (${message}); cancelled to avoid leaking plaintext`, "error");
217	      }
218	      return { cancel: true };
219	    } finally {
220	      persistVaultDelta(pi, redactor);
221	    }
222	  });
223	
224	  pi.on("session_shutdown", async () => {
225	    redactor.dispose();
226	  });
227	}
