1	import { randomInt } from "node:crypto";
2	
3	/** A single persisted vault mapping. */
4	export interface VaultEntry {
5	  token: string;
6	  label: string;
7	  original: string;
8	}
9	
10	/** JSON-serializable, versioned snapshot (or delta) of a vault, suitable for session persistence. */
11	export interface VaultPayload {
12	  v: 1;
13	  nonce: string;
14	  entries: VaultEntry[];
15	}
16	
17	/** A located token inside a text. */
18	export interface TokenSpan {
19	  start: number;
20	  end: number;
21	  token: string;
22	}
23	
24	const NONCE_ALPHABET = "REDACTED";
25	const NONCE_LENGTH = 4;
26	const STRICT_TOKEN_SHAPE = /^\[([A-Z][A-Z0-9_]*)_(\d+)#([a-z0-9]{4})\]$/;
27	
28	function generateNonce(): string {
29	  let out = "";
30	  for (let i = 0; i < NONCE_LENGTH; i++) {
31	    out += NONCE_ALPHABET[randomInt(NONCE_ALPHABET.length)];
32	  }
33	  return out;
34	}
35	
36	function normalizeLabel(label: string): string {
37	  const cleaned = label.toUpperCase().replace(/[^A-Z0-9_]/g, "_");
38	  return /^[A-Z]/.test(cleaned) ? cleaned : `X_${cleaned}`;
39	}
40	
41	/**
42	 * Session-scoped two-way map between sensitive original values and stable tokens
43	 * of the form `[LABEL_N#nonce]`.
44	 *
45	 * - The same original always maps to the same token.
46	 * - Per-label counters only ever increase.
47	 * - The random nonce (created once per vault and persisted with it) makes tokens
48	 *   unforgeable by file contents: text that merely looks like `[EMAIL_1]` is never restored.
49	 */
50	export class PiiVault {
51	  private readonly nonce: string;
52	  private readonly byOriginal = new Map<string, VaultEntry>();
53	  private readonly byToken = REDACTED Map<string, VaultEntry>();
54	  private readonly byKey = new Map<string, VaultEntry>(); // "LABEL_N" -> entry
55	  private readonly counters = new Map<string, number>();
56	  private pending: VaultEntry[] = [];
57	  private readonly strictRegex: RegExp;
58	  private readonly tolerantRegex: RegExp;
59	
60	  constructor(nonce?: string) {
61	    this.nonce = nonce && /^[a-z0-9]{4}$/.test(nonce) ? nonce : generateNonce();
62	    this.strictRegex = new RegExp(`\\[([A-Z][A-Z0-9_]*)_(\\d+)#${this.nonce}\\]`, "g");
63	    const label = "([A-Za-z][A-Za-z0-9_]*)_(\\d+)";
64	    this.tolerantRegex = new RegExp(
65	      `\\[\\s*${label}\\s*#\\s*${this.nonce}\\s*\\]|(?<![A-Za-z0-9_])${label}\\s*#\\s*${this.nonce}(?![A-Za-z0-9])`,
66	      "gi"
67	    );
68	  }
69	
70	  /** Rebuilds a vault from persisted payloads: union of entries, first nonce wins, counters = max N per label. */
71	  public static fromPayloads(payloads: ReadonlyArray<VaultPayload | null | undefined>): PiiVault {
72	    const valid = payloads.filter(
73	      (p): p is VaultPayload =>
74	        !!p && typeof p === "object" && p.v === 1 && typeof p.nonce === "string" && Array.isArray(p.entries)
75	    );
76	    const firstNonce = valid.find((p) => /^[a-z0-9]{4}$/.test(p.nonce))?.nonce;
77	    const vault = new PiiVault(firstNonce);
78	    for (const payload of valid) {
79	      for (const e of payload.entries) {
80	        if (!e || typeof e.token !== "string" || typeof e.label !== "string" || typeof e.original !== "string") {
81	          continue;
82	        }
83	        const m = STRICT_TOKEN_SHAPE.exec(e.token);
84	        if (!m || m[3] !== vault.nonce) continue; // foreign nonce: could never be restored by this vault
85	        vault.insert({ token: e.token, label: m[1], original: e.original }, parseInt(m[2], 10));
86	      }
87	    }
88	    vault.pending = [];
89	    return vault;
90	  }
91	
92	  private insert(entry: VaultEntry, n: number): boolean {
93	    if (this.byToken.has(entry.token) || this.byOriginal.has(entry.original)) return false;
94	    this.byOriginal.set(entry.original, entry);
95	    this.byToken.set(entry.token, entry);
96	    this.byKey.set(`${entry.label}_${n}`, entry);
97	    this.counters.set(entry.label, Math.max(this.counters.get(entry.label) ?? 0, n));
98	    this.pending.push(entry);
99	    return true;
100	  }
101	
102	  /** Returns the existing token for `original`, or mints a new one under `label`. */
103	  public tokenFor(label: string, original: string): string {
104	    const existing = this.byOriginal.get(original);
105	    if (existing) return existing.token;
106	    const norm = normalizeLabel(label);
107	    const n = (this.counters.get(norm) ?? 0) + 1;
108	    const token = `[${norm}_${n}#${this.nonce}]`;
109	    this.insert({ token, label: norm, original }, n);
110	    return token;
111	  }
112	
113	  /** Replaces this vault's tokens (tolerant matching) with their originals. Unknown tokens are left unchanged. */
114	  public restore(text: string): string {
115	    if (!text || typeof text !== "string") return text ?? "";
116	    if (this.byToken.size === 0) return text;
117	    return text.replace(this.tolerantRegex, (match, l1, n1, l2, n2) => {
118	      const label = String(l1 ?? l2).toUpperCase();
119	      const n = parseInt(String(n1 ?? n2), 10);
120	      const entry = this.byKey.get(`${label}_${n}`);
121	      return entry ? entry.original : match;
122	    });
123	  }
124	
125	  /** True if `str` is exactly a canonical token of this vault. */
126	  public isKnownToken(str: string): boolean {
127	    return this.byToken.has(str);
128	  }
129	
130	  /** Locates canonical tokens of this vault inside `text`. */
131	  public findTokens(text: string): TokenSpan[] {
132	    const spans: TokenSpan[] = [];
133	    if (!text || this.byToken.size === 0) return spans;
134	    this.strictRegex.lastIndex = 0;
135	    let m: RegExpExecArray | null;
136	    while ((m = this.strictRegex.exec(text)) !== null) {
137	      if (this.byToken.has(m[0])) {
138	        spans.push({ start: m.index, end: m.index + m[0].length, token: m[0] });
139	      }
140	    }
141	    return spans;
142	  }
143	
144	  /** Known originals with their labels and tokens, longest first. */
145	  public knownOriginals(): VaultEntry[] {
146	    return Array.from(this.byOriginal.values()).sort((a, b) => b.original.length - a.original.length);
147	  }
148	
149	  public get size(): number {
150	    return this.byToken.size;
151	  }
152	
153	  /** Returns entries added since the previous call as a payload, or null if there are none. */
154	  public takePendingDelta(): VaultPayload | null {
155	    if (this.pending.length === 0) return null;
156	    const entries = this.pending;
157	    this.pending = [];
158	    return { v: 1, nonce: this.nonce, entries: entries.map((e) => ({ ...e })) };
159	  }
160	
161	  /** Full JSON-serializable snapshot of the vault. */
162	  public toPayload(): VaultPayload {
163	    return {
164	      v: 1,
165	      nonce: this.nonce,
166	      entries: Array.from(this.byToken.values()).map((e) => ({ ...e })),
167	    };
168	  }
169	}
170

1	import type { ExtensionAPI } from "@earendil-works/pi-coding-agent";
2	import { registerHooks } from "./hooks/index.js";
3	import { registerPiiCommands } from "./commands/pii.js";
4	import { RedactorService } from "./services/redactor.js";
5	
6	export default function (pi: ExtensionAPI) {
