73	      (p): p is VaultPayload =>
74	        !!p && typeof p === "object" && p.v === 1 && typeof p.nonce === "string" && Array.isArray(p.entries)
75	    );
76	    const firstNonce = valid.find((p) => /^[a-z0-9]{4}$/.test(p.nonce))?.nonce;
77	    const vault = new PiiVault(firstNonce);
78	    for (const payload of valid) {
79	      for (const e of payload.entries) {
80	        if (!e || typeof e.token !== "string" || typeof e.label !== "string" || typeof e.original !== "string") {
