84	        if (!m || m[3] !== vault.nonce) continue; // foreign nonce: could never be restored by this vault
85	        vault.insert({ token: e.token, label: m[1], original: e.original }, parseInt(m[2], 10));
86	      }
87	    }
88	    vault.pending = [];
89	    return vault;
90	  }
91	
92	  private insert(entry: VaultEntry, n: number): boolean {
93	    if (this.byToken.has(entry.token) || this.byOriginal.has(entry.original)) return false;
94	    this.byOriginal.set(entry.original, entry);
95	    this.byToken.set(entry.token, entry);
96	    this.byKey.set(`${entry.label}_${n}`, entry);
97	    this.counters.set(entry.label, Math.max(this.counters.get(entry.label) ?? 0, n));
98	    this.pending.push(entry);
99	    return true;
100	  }
