102	  /** Returns the existing token for `original`, or mints a new one under `label`. */
103	  public tokenFor(label: string, original: string): string {
104	    const existing = this.byOriginal.get(original);
105	    if (existing) return existing.token;
106	    const norm = normalizeLabel(label);
107	    const n = (this.counters.get(norm) ?? 0) + 1;
108	    const token = `[${norm}_${n}#${this.nonce}]`;
109	    this.insert({ token, label: norm, original }, n);
110	    return token;
111	  }
112	
113	  /** Replaces this vault's tokens (tolerant matching) with their originals. Unknown tokens are left unchanged. */
114	  public restore(text: string): string {
115	    if (!text || typeof text !== "string") return text ?? "";
116	    if (this.byToken.size === 0) return text;
117	    return text.replace(this.tolerantRegex, (match, l1, n1, l2, n2) => {
118	      const label = String(l1 ?? l2).toUpperCase();
119	      const n = parseInt(String(n1 ?? n2), 10);
120	      const entry = this.byKey.get(`${label}_${n}`);
121	      return entry ? entry.original : match;
122	    });
123	  }
