130	  /** Locates canonical tokens of this vault inside `text`. */
131	  public findTokens(text: string): TokenSpan[] {
132	    const spans: TokenSpan[] = [];
133	    if (!text || this.byToken.size === 0) return spans;
134	    this.strictRegex.lastIndex = 0;
135	    let m: RegExpExecArray | null;
136	    while ((m = this.strictRegex.exec(text)) !== null) {
137	      if (this.byToken.has(m[0])) {
138	        spans.push({ start: m.index, end: m.index + m[0].length, token: m[0] });
139	      }
140	    }
141	    return spans;
142	  }
